#include "aquatic_guardian_app.h"
#include <stdio.h>
#include <string.h>

/* ========================================================================== */
/* External Hardware Handles (Generated by STM32CubeMX)                       */
/* ========================================================================== */
extern ADC_HandleTypeDef  hadc1;
extern TIM_HandleTypeDef  htim2;
extern I2C_HandleTypeDef  hi2c1;
extern UART_HandleTypeDef huart1; /* Dedicated ESP32 Wi-Fi Bridge (PA9/PA10)   */
extern UART_HandleTypeDef huart2; /* Dedicated PC ST-LINK VCP (PA2/PA3)        */

/* 20-sample Circular Buffer for TDS noise suppression (from Quattrone thesis) */
static uint16_t tds_sample_buffer[TDS_FILTER_SAMPLE_COUNT] = {0};
static uint8_t  tds_buffer_head = 0;
static bool     tds_buffer_filled = false;

/* ========================================================================== */
/* FreeRTOS Object Declarations                                               */
/* ========================================================================== */
osThreadId_t         taskSensorHandle;
osThreadId_t         taskDispenserHandle;
osThreadId_t         taskDisplayHandle;
osThreadId_t         taskTelemetryHandle;
osThreadId_t         taskSafetyHandle;

osMutexId_t          i2cBusMutexHandle;
osMutexId_t          uartMutexHandle;
osSemaphoreId_t      feedTriggerSemHandle;
osMessageQueueId_t   telemetryQueueHandle;

/* Task Attributes: CMSIS-RTOS v2 uses BYTES for stack_size! */
const osThreadAttr_t taskSafety_attributes = {
    .name = "SafetySupervisor",
    .stack_size = 1024, /* 1024 Bytes (256 words) */
    .priority = (osPriority_t) osPriorityHigh,
};

const osThreadAttr_t taskDispenser_attributes = {
    .name = "DispenserControl",
    .stack_size = 1024, /* 1024 Bytes (256 words) */
    .priority = (osPriority_t) osPriorityAboveNormal,
};

const osThreadAttr_t taskSensor_attributes = {
    .name = "SensorAcquisition",
    .stack_size = 1024, /* 1024 Bytes (256 words) */
    .priority = (osPriority_t) osPriorityNormal,
};

const osThreadAttr_t taskDisplay_attributes = {
    .name = "DisplayUI",
    .stack_size = 2048, /* 2048 Bytes (512 words) for snprintf & formatting */
    .priority = (osPriority_t) osPriorityBelowNormal,
};

const osThreadAttr_t taskTelemetry_attributes = {
    .name = "Telemetry",
    .stack_size = 2048, /* 2048 Bytes (512 words) for JSON & buffers */
    .priority = (osPriority_t) osPriorityLow,
};

/* ========================================================================== */
/* Initialization                                                             */
/* ========================================================================== */

void AquaticGuardian_Init(void)
{
    /* 1. Create Synchronization Primitives */
    i2cBusMutexHandle    = osMutexNew(NULL);
    uartMutexHandle      = osMutexNew(NULL);
    feedTriggerSemHandle = osSemaphoreNew(1, 0, NULL); /* Binary Semaphore: max=1, initial=0 */
    
    /* Length-1 Non-Destructive Mailbox to prevent consumer starvation */
    telemetryQueueHandle = osMessageQueueNew(SENSOR_MAILBOX_LENGTH, sizeof(AquariumTelemetry_t), NULL);

    /* 2. Instantiate Multitasking Threads */
    taskSafetyHandle    = osThreadNew(Task_SafetySupervisor_Entry, NULL, &taskSafety_attributes);
    taskDispenserHandle = osThreadNew(Task_DispenserControl_Entry, NULL, &taskDispenser_attributes);
    taskSensorHandle    = osThreadNew(Task_SensorAcquisition_Entry, NULL, &taskSensor_attributes);
    taskDisplayHandle   = osThreadNew(Task_DisplayUI_Entry, NULL, &taskDisplay_attributes);
    taskTelemetryHandle = osThreadNew(Task_Telemetry_Entry, NULL, &taskTelemetry_attributes);

    /* 3. Initialize Actuators to Safe Idle State */
    AquaticGuardian_SetServoAngle(SERVO_FEED_ANGLE_CLOSED);
    AquaticGuardian_SetAlarmState(false);
    AquaticGuardian_SetRelayState(true); /* Pump ON by default */
}

/* ========================================================================== */
/* FreeRTOS Tasks Implementation                                              */
/* ========================================================================== */

/**
 * @brief  Task 1: Sensor Data Acquisition (Period: 1000ms)
 *         Reads ADC channels individually (preventing DR overwrite).
 *         Filters TDS via 20-sample ring buffer, overwrites length-1 mailbox.
 */
void Task_SensorAcquisition_Entry(void *argument)
{
    AquariumTelemetry_t packet;
    uint32_t simulated_time = 0;

    for (;;)
    {
        /* --- Dynamic Channel Polling: Prevents STM32F4 ADC1->DR Overwrite --- */
        packet.raw_tds_adc = AquaticGuardian_ReadADCChannel(ADC_CHANNEL_1);
        packet.raw_pot_adc = AquaticGuardian_ReadADCChannel(ADC_CHANNEL_4);

        /* --- 20-Sample Moving Average Filter (Thesis Section 3.2.2.5) --- */
        tds_sample_buffer[tds_buffer_head++] = packet.raw_tds_adc;
        if (tds_buffer_head >= TDS_FILTER_SAMPLE_COUNT) {
            tds_buffer_head = 0;
            tds_buffer_filled = true;
        }

        uint32_t adc_accum = 0;
        uint8_t num_samples = tds_buffer_filled ? TDS_FILTER_SAMPLE_COUNT : tds_buffer_head;
        if (num_samples == 0) num_samples = 1;
        for (uint8_t i = 0; i < num_samples; i++) {
            adc_accum += tds_sample_buffer[i];
        }
        uint16_t filtered_tds_adc = (uint16_t)(adc_accum / num_samples);

        /* --- Read Temperature & Calculate Compensated TDS --- */
        packet.water_temp_celsius = AquaticGuardian_ReadWaterTemperature();
        packet.tds_ppm = AquaticGuardian_CalculateTDS(filtered_tds_adc, packet.water_temp_celsius);
        packet.portion_grams = (uint8_t)((packet.raw_pot_adc * 15) / 4095) + 1; /* 1 - 15 grams */
        packet.timestamp_sec = ++simulated_time;

        /* Classify Water State */
        if (packet.tds_ppm < TDS_SAFE_THRESHOLD_PPM && packet.water_temp_celsius <= TEMP_SAFE_MAX_CELSIUS) {
            packet.water_status = WATER_STATUS_OPTIMAL;
        } else if (packet.tds_ppm < TDS_WARNING_THRESHOLD_PPM && packet.water_temp_celsius < TEMP_DANGER_MAX_CELSIUS) {
            packet.water_status = WATER_STATUS_ACCEPTABLE;
        } else if (packet.tds_ppm < TDS_DANGER_THRESHOLD_PPM) {
            packet.water_status = WATER_STATUS_WARNING;
        } else {
            packet.water_status = WATER_STATUS_CRITICAL;
        }

        /* Overwrite Length-1 Mailbox (Non-blocking): Always keeps freshest state */
        osMessageQueuePut(telemetryQueueHandle, &packet, 0U, 0);

        /* Block for 1000ms: Yields CPU to lower/higher priority tasks */
        osDelay(1000);
    }
}

/**
 * @brief  Task 2: Dispenser Actuation (Event-Driven)
 *         Blocks on feedTriggerSemHandle. Wakes up when signaled by button ISR,
 *         RTC schedule, or Telegram /feed command.
 *         Demonstrates Priority Inheritance: Locks i2cBusMutex to log to EEPROM!
 */
void Task_DispenserControl_Entry(void *argument)
{
    static uint32_t feed_counter = 0;

    for (;;)
    {
        /* Block permanently until an event signals the semaphore */
        if (osSemaphoreAcquire(feedTriggerSemHandle, osWaitForever) == osOK)
        {
            /* Visual indicator: Blink Green LED */
            HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET);

            /* Dynamic Portion Dwell Time based on Potentiometer reading */
            AquariumTelemetry_t snap;
            uint32_t dwell_ms = 800;
            if (osMessageQueuePeek(telemetryQueueHandle, &snap, NULL, 0) == osOK)
            {
                dwell_ms = 300U + ((uint32_t)snap.portion_grams * 80U); /* 380ms - 1500ms */
            }

            /* Step 1: Rotate Servo to Open Position (90 deg) */
            AquaticGuardian_SetServoAngle(SERVO_FEED_ANGLE_OPEN);
            osDelay(dwell_ms); /* Food pellets drop into tank */

            /* Step 2: Return Servo to Closed Position (0 deg) */
            AquaticGuardian_SetServoAngle(SERVO_FEED_ANGLE_CLOSED);
            osDelay(400);

            feed_counter++;

            /* Step 3: Priority Inheritance Proof on I2C1 Bus */
            /* AboveNormal task acquires i2cBusMutex to write feed event to AT24C32 EEPROM */
            if (osMutexAcquire(i2cBusMutexHandle, 100) == osOK)
            {
                AquaticGuardian_LogFeedToEEPROM(HAL_GetTick() / 1000, (uint8_t)feed_counter);
                osMutexRelease(i2cBusMutexHandle);
            }

            HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET);
        }
    }
}

/**
 * @brief  Task 3: Safety Supervisor (Period: 200ms)
 *         Non-destructively peeks the mailbox. If water is dangerous or overheated,
 *         triggers buzzer and flashes Red Hazard LED.
 */
void Task_SafetySupervisor_Entry(void *argument)
{
    AquariumTelemetry_t latest_data;

    for (;;)
    {
        /* Non-destructive Peek: Leaves mailbox intact for Display & Telemetry! */
        if (osMessageQueuePeek(telemetryQueueHandle, &latest_data, NULL, 0) == osOK)
        {
            if (latest_data.water_status == WATER_STATUS_CRITICAL)
            {
                /* Sound buzzer alarm & flash Red Alert LED (PB1) */
                AquaticGuardian_SetAlarmState(true);
                HAL_GPIO_TogglePin(GPIOB, GPIO_PIN_1);
            }
            else if (latest_data.water_status == WATER_STATUS_WARNING)
            {
                /* Solid Red Warning LED, silent buzzer */
                AquaticGuardian_SetAlarmState(false);
                HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_SET);
            }
            else
            {
                /* Normal: Alarm OFF, Warning LED OFF, Green LED ON */
                AquaticGuardian_SetAlarmState(false);
                HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_RESET);
                HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET);
            }
        }

        osDelay(200);
    }
}

/**
 * @brief  Task 4: Display UI (Period: 500ms)
 *         Non-destructively peeks mailbox. Acquires i2cBusMutex to read RTC
 *         and update LCD 2004 / 1602.
 */
void Task_DisplayUI_Entry(void *argument)
{
    AquariumTelemetry_t display_data;
    char line1_buf[21];
    char line2_buf[21];
    uint8_t hrs = 12, min = 0, sec = 0;

    /* Initialize LCD backpack under mutex protection */
    if (osMutexAcquire(i2cBusMutexHandle, 500) == osOK)
    {
        AquaticGuardian_LCD_Init();
        AquaticGuardian_LCD_SetCursor(0, 0);
        AquaticGuardian_LCD_Print("Aquatic Guardian 2.0");
        AquaticGuardian_LCD_SetCursor(1, 0);
        AquaticGuardian_LCD_Print("System Booting...");
        osMutexRelease(i2cBusMutexHandle);
    }
    osDelay(1500);

    for (;;)
    {
        if (osMessageQueuePeek(telemetryQueueHandle, &display_data, NULL, 0) == osOK)
        {
            /* CRITICAL SECTION: Lock shared I2C bus */
            if (osMutexAcquire(i2cBusMutexHandle, 100) == osOK)
            {
                /* Read real-time clock from DS3231 (0x68) */
                AquaticGuardian_DS3231_ReadTime(&hrs, &min, &sec);

                snprintf(line1_buf, sizeof(line1_buf), "TDS:%4.0f %02u:%02u:%02u",
                         display_data.tds_ppm, hrs, min, sec);
                snprintf(line2_buf, sizeof(line2_buf), "P:%2dg T:%2.1fC %s",
                         display_data.portion_grams, display_data.water_temp_celsius,
                         (display_data.water_status <= WATER_STATUS_ACCEPTABLE) ? "OK " : "ERR");

                AquaticGuardian_LCD_SetCursor(0, 0);
                AquaticGuardian_LCD_Print(line1_buf);
                AquaticGuardian_LCD_SetCursor(1, 0);
                AquaticGuardian_LCD_Print(line2_buf);

                osMutexRelease(i2cBusMutexHandle);
            }
        }

        osDelay(500);
    }
}

/**
 * @brief  Task 5: Serial Telemetry (Period: 2000ms)
 *         Non-destructively peeks mailbox. Broadcasts JSON over USART1 (ESP32)
 *         and USART2 (PC VCP) with '~' delimiter.
 */
void Task_Telemetry_Entry(void *argument)
{
    AquariumTelemetry_t packet;
    char tx_buffer[TELEMETRY_BUFFER_SIZE];

    for (;;)
    {
        if (osMessageQueuePeek(telemetryQueueHandle, &packet, NULL, 0) == osOK)
        {
            int len = snprintf(tx_buffer, sizeof(tx_buffer),
                "{\"time\":%lu,\"tds_ppm\":%.1f,\"portion_g\":%d,\"temp_c\":%.1f,\"status\":%d}~\r\n",
                (unsigned long)packet.timestamp_sec, packet.tds_ppm, packet.portion_grams,
                packet.water_temp_celsius, (int)packet.water_status);

            if (len > 0)
            {
                if (osMutexAcquire(uartMutexHandle, 100) == osOK)
                {
                    /* Send to PC via ST-LINK VCP */
                    HAL_UART_Transmit(&huart2, (uint8_t*)tx_buffer, (uint16_t)len, 50);
                    /* Send to ESP32 Wi-Fi Co-Processor */
                    HAL_UART_Transmit(&huart1, (uint8_t*)tx_buffer, (uint16_t)len, 50);
                    osMutexRelease(uartMutexHandle);
                }
            }
        }

        osDelay(2000);
    }
}

/* ========================================================================== */
/* Interrupt Service Routine (Debounced Deferred Interrupt Processing)        */
/* ========================================================================== */

/**
 * @brief  Hardware EXTI Callback for User Button (PC13)
 *         Enforces 300ms software tick debounce guard!
 */
void AquaticGuardian_OnButtonPressed_ISR(uint16_t GPIO_Pin)
{
    static uint32_t last_exti_tick = 0;

    if (GPIO_Pin == GPIO_PIN_13) /* Blue User Button */
    {
        uint32_t now = HAL_GetTick();
        if ((now - last_exti_tick) > 300U)
        {
            last_exti_tick = now;
            if (feedTriggerSemHandle != NULL)
            {
                osSemaphoreRelease(feedTriggerSemHandle);
            }
        }
    }
}

/* ========================================================================== */
/* Hardware Control & Calibration Helpers                                     */
/* ========================================================================== */

/**
 * @brief  Read single ADC channel dynamically to prevent ADC1->DR overwrite.
 */
uint16_t AquaticGuardian_ReadADCChannel(uint32_t channel)
{
    ADC_ChannelConfTypeDef sConfig = {0};
    sConfig.Channel = channel;
    sConfig.Rank = 1;
    sConfig.SamplingTime = ADC_SAMPLETIME_84CYCLES;
    HAL_ADC_ConfigChannel(&hadc1, &sConfig);

    HAL_ADC_Start(&hadc1);
    uint16_t val = 0;
    if (HAL_ADC_PollForConversion(&hadc1, 10) == HAL_OK) {
        val = (uint16_t)HAL_ADC_GetValue(&hadc1);
    }
    HAL_ADC_Stop(&hadc1);
    return val;
}

/**
 * @brief  Read water temperature from DS3231 internal temperature register (0x11-0x12).
 *         Provides 0.25 deg C resolution over I2C1 without requiring external DS18B20 wire!
 */
float AquaticGuardian_ReadWaterTemperature(void)
{
    uint8_t reg = 0x11;
    uint8_t temp_buf[2] = {0};

    /* Attempt to read DS3231 temperature register (Address 0x68) */
    if (HAL_I2C_Master_Transmit(&hi2c1, (0x68 << 1), &reg, 1, 50) == HAL_OK &&
        HAL_I2C_Master_Receive(&hi2c1, (0x68 << 1), temp_buf, 2, 50) == HAL_OK)
    {
        int8_t temp_msb = (int8_t)temp_buf[0];
        float temp_lsb = (float)((temp_buf[1] >> 6) & 0x03) * 0.25f;
        return (float)temp_msb + temp_lsb;
    }

    /* Fallback default ambient aquarium temperature */
    return 26.5f;
}

/**
 * @brief  Calculate TDS ppm using exact temperature-compensated cubic formula.
 *         Formula: TDS = (133.42 * V^3 - 255.86 * V^2 + 857.39 * V) * 0.5
 */
float AquaticGuardian_CalculateTDS(uint16_t raw_adc, float temperature_c)
{
    float voltage = ((float)raw_adc / 4095.0f) * 3.3f;
    float temp_compensation = 1.0f + 0.02f * (temperature_c - 25.0f);
    if (temp_compensation <= 0.1f) temp_compensation = 1.0f;
    float compensated_voltage = voltage / temp_compensation;

    float tds = (133.42f * compensated_voltage * compensated_voltage * compensated_voltage
               - 255.86f * compensated_voltage * compensated_voltage
               + 857.39f * compensated_voltage) * 0.5f;

    if (tds < 0.0f) tds = 0.0f;
    return tds;
}

/**
 * @brief  Set SG90 Servo angle using Timer PWM Compare register.
 */
void AquaticGuardian_SetServoAngle(uint8_t angle_deg)
{
    if (angle_deg > 180) angle_deg = 180;
    uint32_t pulse = SERVO_PULSE_MIN_TICKS + ((uint32_t)angle_deg * (SERVO_PULSE_MAX_TICKS - SERVO_PULSE_MIN_TICKS)) / 180;
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, pulse);
}

/**
 * @brief  Dispense food portion with dwell time dynamically scaled by grams (1-15g).
 */
void AquaticGuardian_DispensePortion(uint8_t grams)
{
    if (grams < 1) grams = 1;
    if (grams > 15) grams = 15;
    uint32_t dwell_ms = 300U + ((uint32_t)grams * 80U);
    AquaticGuardian_SetServoAngle(SERVO_FEED_ANGLE_OPEN);
    osDelay(dwell_ms);
    AquaticGuardian_SetServoAngle(SERVO_FEED_ANGLE_CLOSED);
    osDelay(300);
}

void AquaticGuardian_SetAlarmState(bool active)
{
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, active ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

void AquaticGuardian_SetRelayState(bool active)
{
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_4, active ? GPIO_PIN_RESET : GPIO_PIN_SET);
}

/**
 * @brief  Log feed event to AT24C32 EEPROM over shared I2C1 bus.
 *         Address: 0x57. Writes 8-byte record at 0x0000: [0xAA, portion, timestamp(4B)]
 */
bool AquaticGuardian_LogFeedToEEPROM(uint32_t timestamp, uint8_t portion)
{
    uint8_t payload[8];
    payload[0] = 0x00; /* EEPROM Word Address MSB */
    payload[1] = 0x00; /* EEPROM Word Address LSB */
    payload[2] = 0xAA; /* Magic Header */
    payload[3] = portion;
    payload[4] = (uint8_t)((timestamp >> 24) & 0xFF);
    payload[5] = (uint8_t)((timestamp >> 16) & 0xFF);
    payload[6] = (uint8_t)((timestamp >> 8)  & 0xFF);
    payload[7] = (uint8_t)(timestamp & 0xFF);

    if (HAL_I2C_Master_Transmit(&hi2c1, (0x57 << 1), payload, 8, 100) == HAL_OK)
    {
        osDelay(10); /* EEPROM write cycle delay (tWR = 5ms max) */
        return true;
    }
    return false;
}

/* ========================================================================== */
/* LCD2004 PCF8574 Backpack I2C Driver Implementation                         */
/* ========================================================================== */

#define LCD_I2C_ADDR (0x27U << 1) /* 8-bit HAL I2C address */
#define LCD_BACKLIGHT 0x08U
#define LCD_ENABLE    0x04U

static void LCD_WriteNibble(uint8_t nibble, uint8_t rs)
{
    uint8_t data = (nibble & 0xF0) | (rs ? 0x01 : 0x00) | LCD_BACKLIGHT;
    uint8_t buf[2];
    buf[0] = data | LCD_ENABLE;
    buf[1] = data & ~LCD_ENABLE;
    HAL_I2C_Master_Transmit(&hi2c1, LCD_I2C_ADDR, buf, 2, 50);
}

static void LCD_SendCmd(uint8_t cmd)
{
    LCD_WriteNibble(cmd & 0xF0, 0);
    LCD_WriteNibble((cmd << 4) & 0xF0, 0);
    osDelay(2);
}

static void LCD_SendData(uint8_t data)
{
    LCD_WriteNibble(data & 0xF0, 1);
    LCD_WriteNibble((data << 4) & 0xF0, 1);
}

void AquaticGuardian_LCD_Init(void)
{
    osDelay(50);
    LCD_WriteNibble(0x30, 0); osDelay(5);
    LCD_WriteNibble(0x30, 0); osDelay(1);
    LCD_WriteNibble(0x30, 0); osDelay(1);
    LCD_WriteNibble(0x20, 0); osDelay(1); /* 4-bit interface */

    LCD_SendCmd(0x28); /* 2-line mode, 5x8 font */
    LCD_SendCmd(0x0C); /* Display ON, Cursor OFF */
    LCD_SendCmd(0x06); /* Entry mode: auto-increment */
    LCD_SendCmd(0x01); /* Clear display */
    osDelay(5);
}

void AquaticGuardian_LCD_SetCursor(uint8_t row, uint8_t col)
{
    uint8_t row_offsets[] = {0x00, 0x40, 0x14, 0x54};
    LCD_SendCmd(0x80 | (col + row_offsets[row % 4]));
}

void AquaticGuardian_LCD_Print(const char *str)
{
    while (*str) {
        LCD_SendData((uint8_t)*str++);
    }
}

/* ========================================================================== */
/* DS3231 Precision Real-Time Clock I2C Driver Implementation                */
/* ========================================================================== */

#define DS3231_I2C_ADDR (0x68U << 1)

bool AquaticGuardian_DS3231_ReadTime(uint8_t *hrs, uint8_t *min, uint8_t *sec)
{
    uint8_t reg = 0x00;
    uint8_t raw[3] = {0};

    if (HAL_I2C_Master_Transmit(&hi2c1, DS3231_I2C_ADDR, &reg, 1, 50) == HAL_OK &&
        HAL_I2C_Master_Receive(&hi2c1, DS3231_I2C_ADDR, raw, 3, 50) == HAL_OK)
    {
        *sec = ((raw[0] >> 4) * 10) + (raw[0] & 0x0F);
        *min = ((raw[1] >> 4) * 10) + (raw[1] & 0x0F);
        *hrs = ((raw[2] & 0x1F) >> 4) * 10 + (raw[2] & 0x0F);
        return true;
    }
    return false;
}
